cd /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/uv && python3 - <<'PY'
import pathlib
ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')

for rel, line in [('src/main.rs', 'mod dir_prelude;'), ('src/lib.rs', 'pub mod dir_prelude;')]:
    p = ROOT / rel
    t = p.read_text()
    assert t.count(line) == 1, rel
    p.write_text(t.replace(line, line + '\n' + line.replace('dir_prelude', 'gz_prelude')))
    print(f'{rel}: gz_prelude declared')

p = ROOT / 'src/pipeline.rs'
t = p.read_text()
old = '''    crate::progress::phase("dir-prelude");
    let phase_started = Instant::now();
    let ast = crate::dir_prelude::inject_if_used(ast);
    timings.record_since("dir-prelude", phase_started);'''
new = '''    crate::progress::phase("dir-prelude");
    let phase_started = Instant::now();
    let ast = crate::dir_prelude::inject_if_used(ast);
    timings.record_since("dir-prelude", phase_started);

    // php's `gz*` stream surface, spelled as the `compress.zlib://` wrapper the stream builtins
    // already serve, injected only when the program references one of those functions. Runs beside
    // the other preludes, after include resolution so a reference inside an include is detected,
    // and before name resolution so a namespaced caller resolves to it.
    crate::progress::phase("gz-prelude");
    let phase_started = Instant::now();
    let ast = crate::gz_prelude::inject_if_used(ast);
    timings.record_since("gz-prelude", phase_started);'''
assert t.count(old) == 1, 'pipeline anchor not found'
p.write_text(t.replace(old, new))
print('pipeline.rs: the gz prelude is injected')

p = ROOT / 'src/ir_lower/tests/mod.rs'
t = p.read_text()
old = '    let ast = crate::dir_prelude::inject_if_used(ast);'
new = '    let ast = crate::dir_prelude::inject_if_used(ast);\n    let ast = crate::gz_prelude::inject_if_used(ast);'
assert t.count(old) == 1, 'ir_lower test harness anchor not found'
p.write_text(t.replace(old, new))
print('ir_lower/tests/mod.rs: the harness injects it too')
